import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BsgK4TUM.js";const p=JSON.parse('{"title":"Creating Payment Methods","description":"","frontmatter":{},"headers":[],"relativePath":"developers/payment_methods.md","filePath":"developers/payment_methods.md"}'),r={name:"developers/payment_methods.md"};function i(d,e,n,c,h,m){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="creating-payment-methods" tabindex="-1">Creating Payment Methods <a class="header-anchor" href="#creating-payment-methods" aria-label="Permalink to &quot;Creating Payment Methods&quot;">​</a></h1><p>Like Shipping Methods, new Payment methods are added to Community Store through additional add-ons.</p><p>Each payment processor has their own requirements and way of integration, but they can generally be placed into one of two categories:</p><ol><li>A customer entered payment details (such as for a credit card) either directly within the checkout or in a modal popup, and submits a <code>token</code>, which is then used to process payment</li><li>The customer is taken off-site to a hosted payment page, where they make a payment and are returned back to the website afterwards.</li></ol><p>Whilst the first approach provides a more seamless experience for the customer, increasingly strict regulations make this increasingly difficult to accommodate across all markets. For example, in the EU it is now a requirement that payment systems are Strong Customer Authentication (SCA) compliant. This is easiest to achieve with off-site payment systems such as Stripe Checkout or Paypal.</p><p>If you are looking to develop a new payment method add-on for a payment gateway, it is recommended that you opt for a gateway&#39;s latest and recommended integration technique.</p><p>The <a href="https://github.com/concretecms-community-store/community_store_stripe_checkout" target="_blank" rel="noreferrer">Stripe Checkout payment add-on</a> is a good example of an off-site payment process.</p><h2 id="structure-of-a-payment-method" tabindex="-1">Structure of a payment method <a class="header-anchor" href="#structure-of-a-payment-method" aria-label="Permalink to &quot;Structure of a payment method&quot;">​</a></h2><p>A payment method add-on&#39;s structure is as follows:</p><ul><li>A package, with a package controller.php, used to install the package and add the new payment method, e.g. <code>PaymentMethod::add(&#39;my_payment_method&#39;, &#39;My Payment Method&#39;, $pkg)</code></li><li>A payment method class, extending <code>\\Concrete\\Package\\CommunityStore\\Src\\CommunityStore\\Payment\\Method</code>. It is named after the method&#39;s handle, e.g. for a handle <code>my_payment_method</code>, the class <code>MyPaymentMethodPaymentMethod</code> in the namespace <code>Concrete\\Package\\&lt;PackageHandle&gt;\\Src\\CommunityStore\\Payment\\Methods\\MyPaymentMethod</code>, within <code>src/CommunityStore/Payment/Methods/MyPaymentMethod/</code></li><li>Element files, within an <code>elements</code> folder named after the payment method&#39;s handle: <ul><li><code>dashboard_form.php</code> - the method&#39;s settings form, shown in the Payments section of <strong>Store / Settings</strong></li><li><code>checkout_form.php</code> - output within the checkout when the method is selected</li><li><code>redirect_form.php</code> - for off-site payment methods, the form used to send the customer to the payment gateway</li></ul></li></ul><h3 id="methods-to-implement" tabindex="-1">Methods to implement <a class="header-anchor" href="#methods-to-implement" aria-label="Permalink to &quot;Methods to implement&quot;">​</a></h3><ul><li><code>getName()</code> - the name of the payment method</li><li><code>dashboardForm()</code> - sets the values used by the <code>dashboard_form</code> element</li><li><code>save(array $data)</code> - saves the method&#39;s settings from the Dashboard form</li><li><code>validate($args, $e)</code> - validates the Dashboard form, adding any errors to <code>$e</code></li><li><code>checkoutForm()</code> - sets the values used by the <code>checkout_form</code> element</li><li><code>submitPayment()</code> - for on-site payments, processes the payment when the order is submitted. It returns an array: <code>[&#39;error&#39; =&gt; 0, &#39;transactionReference&#39; =&gt; &#39;...&#39;]</code> on success, or <code>[&#39;error&#39; =&gt; 1, &#39;errorMessage&#39; =&gt; &#39;...&#39;]</code> on failure</li><li><code>getPaymentMinimum()</code> / <code>getPaymentMaximum()</code> - the order totals the method is available for</li></ul><h3 id="optional-methods" tabindex="-1">Optional methods <a class="header-anchor" href="#optional-methods" aria-label="Permalink to &quot;Optional methods&quot;">​</a></h3><ul><li><code>headerScripts($view)</code> - called on the checkout page, so the method can add any scripts or assets it needs (for example a gateway&#39;s JavaScript library)</li><li><code>isExternal()</code> - return <code>true</code> for off-site payment methods</li><li><code>getAction()</code> - for off-site payment methods, the URL the customer is sent to</li><li><code>redirectForm()</code> - for off-site payment methods, sets the values used by the <code>redirect_form</code> element</li><li><code>isExternalActionGET()</code> - return <code>true</code> if the customer should be sent to the <code>getAction()</code> URL with a GET request, instead of submitting the redirect form</li><li><code>markPaid()</code> - return <code>false</code> if completing an order with this method should not mark it as paid (as with the Invoice method)</li><li><code>sendReceipt()</code> - return <code>false</code> to not send a receipt when the order is completed</li><li><code>getPaymentInstructions()</code> - instructions to display to the customer (and translatable via <strong>Store / Multilingual</strong>)</li></ul><h3 id="completing-orders-from-off-site-payments" tabindex="-1">Completing orders from off-site payments <a class="header-anchor" href="#completing-orders-from-off-site-payments" aria-label="Permalink to &quot;Completing orders from off-site payments&quot;">​</a></h3><p>For off-site payment methods, the order is created with an &#39;incomplete&#39; status before the customer is sent to the payment gateway. The add-on registers its own route to handle the gateway&#39;s response or webhook, and once the payment is confirmed calls:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$order</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">completeOrder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($transactionReference);</span></span></code></pre></div><p>This marks the order as paid, sends the notification and receipt emails, and performs other post-purchase processes such as creating user accounts.</p><p>The checkout page submits the redirect form using JavaScript. A payment method can add a <code>submit</code> listener to the form (<code>#store-checkout-redirect-form</code>) and call <code>preventDefault()</code> to stop the redirect, for example if an error has occurred.</p>',19)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
